/* bundle.js v2: 不改 mock.js, 而是在它前面塞一个 XHR 垫片, 把各层文件内容直接喂给它自己的 fetch 循环。
   这样避免了字符串切割带来的语法破坏。生成 build/mock.bundle.js */
const fs = require('fs');
const B = '/data/data/com.dsharnessmobile.shell/files/home/.dsh/workspaces/incoming/lxqw/';
const read = p => fs.readFileSync(B + p, 'utf8');
const mock = read('new/mock.js');
const extra = (mock.match(/var extra = \[([^\]]*)\]/) || [,''])[1].split(',').map(s => s.trim().replace(/["']/g,'')).filter(Boolean);
const files = {};
['semantic.js','defaults.js','rules.js'].concat(extra).forEach(f => { try { files[f] = read('new/' + f); } catch (e) { console.log('skip', f); } });
const out = [
  '/* lxqw offline mock bundle - generated by tools/bundle.js (v2 shim approach) */',
  '(function(){',
  '  var FILES = ' + JSON.stringify(files) + ';',
  '  var Orig = window.XMLHttpRequest;',
  '  function Shim(){',
  '    var self = this, orig = new Orig();',
  '    this.readyState = 0; this.status = 200; this.responseText = \'\';',
  '    this.open = function(m, u, a){ self.m = m; self.u = String(u); try { orig.open(m, u, a !== false); } catch(e){} };',
  '      try { window.__bundleUrls = window.__bundleUrls || []; window.__bundleUrls.push(String(u)); } catch (e) {}',
  '    this.setRequestHeader = function(){ try { orig.setRequestHeader.apply(orig, arguments); } catch(e){} };',
  '    this.send = function(body){',
  '      var m = /[a-z0-9_.]+[.]js/.exec(self.u);',
  '      if (m && FILES[m[0]] === undefined) { try { console.log(\'[BUNDLE-MISS] \' + m[0]); } catch (e) {} }',
  '      if (m && FILES[m[0]] !== undefined) { window.__bundleHits = (window.__bundleHits || 0) + 1; }',
  '      if (m && FILES[m[1]] !== undefined) { self.responseText = FILES[m[1]]; self.status = 200; return; }',
  '      if (m) { self.responseText = \'\'; self.status = 404; return; }',
  '      return orig.send.apply(orig, arguments);',
  '    };',
  '  }',
  '  window.XMLHttpRequest = Shim;',
  '})();',
  mock,
].join('\n');
fs.mkdirSync(B + 'build', { recursive: true });
fs.writeFileSync(B + 'build/mock.bundle.js', out);
console.log('inlined files:', Object.keys(files).length, 'bundle bytes:', out.length);